def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opp_bids = []
    rich_opp_bids = []

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                    urgent_opp_bids.append(float(bid))
                if opp.get('budget', 0) >= 200:
                    rich_opp_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 20.0))

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    scarcity = slots <= 1
    medium_tight = slots == 2

    highest_prev = max(prev_bids) if prev_bids else 0.0
    urgent_prev = max(urgent_opp_bids) if urgent_opp_bids else highest_prev
    rich_prev = max(rich_opp_bids) if rich_opp_bids else highest_prev

    my_urgent = hp <= 3 or no_water_days >= 1
    very_urgent = hp <= 2 or no_water_days >= 2

    if very_urgent:
        target = max(90.0, highest_prev + 2.0)
        if scarcity:
            target = max(target, rich_prev + 2.5, 108.0)
        return float(min(budget, target))

    if my_urgent:
        target = max(78.0, urgent_prev + 1.5)
        if scarcity:
            target = max(target, highest_prev + 2.0, 96.0)
        return float(min(budget, target))

    if scarcity:
        if highest_prev >= 105.0:
            target = 58.0
        elif highest_prev >= 90.0:
            target = 64.0
        else:
            target = max(66.0, highest_prev + 1.5)
    elif medium_tight:
        if highest_prev >= 105.0:
            target = 46.0
        elif highest_prev >= 90.0:
            target = 52.0
        else:
            target = max(48.0, highest_prev * 0.72)
    else:
        if highest_prev >= 100.0:
            target = 32.0
        elif highest_prev >= 80.0:
            target = 38.0
        else:
            target = 42.0

    if day >= 8 and hp >= 5:
        target *= 0.92

    if budget < 120:
        target = min(target, 55.0)
    elif budget > 400 and scarcity:
        target = max(target, 68.0)

    return float(max(0.0, min(budget, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_current_budget = my_status['budget']
    my_current_hp = my_status['hp']
    current_day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_current_budget, DAILY_SALARY * 0.1)

    yesterday_bids = []
    david_is_alive = False
    david_prev_bid = 0.0

    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev_trace = opp.get('previous_trace', {})
            if prev_trace and prev_trace.get('bid') is not None:
                yesterday_bids.append(prev_trace['bid'])
            if opp_id == "David":
                david_is_alive = True
                if prev_trace and prev_trace.get('bid') is not None:
                    david_prev_bid = prev_trace['bid']

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    competitive_bid_floor = DAILY_SALARY * 0.6

    if david_is_alive and david_prev_bid > 0:
        competitive_bid_floor = max(competitive_bid_floor, david_prev_bid * 1.05)

    if highest_prev_bid > 0:
        competitive_bid_floor = max(competitive_bid_floor, highest_prev_bid * 1.02)

    competitive_bid_floor = max(competitive_bid_floor, DAILY_SALARY * 0.5)

    bid = competitive_bid_floor

    if my_current_hp <= 2:
        bid = max(bid, DAILY_SALARY * 0.95)
    elif my_current_hp <= 5:
        bid = max(bid, DAILY_SALARY * 0.8)

    days_remaining = EPISODE_DAYS - current_day
    if days_remaining <= 2:
        if my_current_hp <= 5:
            bid = max(bid, DAILY_SALARY * 0.98)
        else:
            bid = max(bid, DAILY_SALARY * 0.85)

    final_bid = min(my_current_budget, bid)

    return max(1.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 1)

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    if not alive:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Inspect only yesterday's behavior from previous_trace
    prev_bids = []
    prev_pressures = []
    for opp_id, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass
        # Use hp_after as a proxy for how costly their bid was
        hp_after = prev.get('hp_after', None)
        if hp_after is not None:
            try:
                prev_pressures.append((opp_id, float(hp_after)))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # Identify if Bob-like aggressive bidding is present
    bob_like = False
    for opp_id, opp in alive:
        if str(opp_id).lower() == 'bob':
            prev = opp.get('previous_trace', {}) or {}
            b = prev.get('bid', None)
            if b is not None:
                try:
                    if float(b) >= DAILY_SALARY * 0.8:
                        bob_like = True
                except Exception:
                    pass

    # Supply-based urgency: if supply is tight relative to requirement, increase bid.
    # supply is between 15 and 25 in this meta-round.
    # Approx water units available ~ supply / WATER_REQ.
    supply_units = supply / float(WATER_REQ) if WATER_REQ > 0 else 0.0
    tight = supply_units < 3.0  # when supply < 21

    # Base bid policy
    # If my hp is low or I have accumulated no-water days, bid aggressively.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        target = DAILY_SALARY * (0.85 if tight else 0.75)
    else:
        # Otherwise, react to opponent aggressiveness without overspending.
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            # Bob/Cindy were spending; bid enough to avoid being starved, but not match Cindy.
            target = max(DAILY_SALARY * 0.55, highest_prev_bid * 0.55)
        elif highest_prev_bid >= DAILY_SALARY * 0.5 or bob_like:
            target = max(DAILY_SALARY * 0.5, highest_prev_bid * 0.5)
        else:
            target = DAILY_SALARY * (0.45 if not tight else 0.6)

    # Early days: slightly more aggressive to secure survival.
    if int(day) <= 3:
        target *= 1.08

    # Clamp to budget and avoid negative
    bid = max(0.0, min(my_budget, float(target)))
    return bid
